class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        # Count frequency of each number
        count = Counter(nums)

        max_length = 0

        # Try each unique number as the base value x
        for x in count:
            # Special case: x = 1
            if x == 1:
                # For 1s: pattern can be [1,1,1,1,...] - all 1s
                # Maximum length is the total count of 1s
                max_length = max(max_length, count[1])
                continue

            # For x > 1, build the sequence: x, x^2, x^4, x^8, ...
            sequence = []
            current = x

            while current in count and current <= 10**9:
                sequence.append(current)
                # Next power of 2 in exponent
                next_val = current * current
                if next_val > 10**9:
                    break
                current = next_val

            # Now try all possible pattern lengths from sequence
            # Pattern length must be odd (center element) or even (symmetric without center)
            for length in range(1, len(sequence) + 1):
                # Check if we can form a pattern of this length
                if length == 1:
                    # Single element pattern
                    if count[sequence[0]] >= 1:
                        max_length = max(max_length, 1)
                else:
                    # For length > 1
                    if length % 2 == 1:
                        # Odd length: has center element
                        # Left side: length//2 elements, each needs 2 copies
                        # Center: needs 1 copy
                        left_count = length // 2
                        valid = True

                        for i in range(left_count):
                            if count[sequence[i]] < 2:
                                valid = False
                                break

                        if valid and count[sequence[length//2]] >= 1:
                            max_length = max(max_length, length)
                    else:
                        # Even length: symmetric without center
                        # Left side: length//2 elements, each needs 2 copies
                        left_count = length // 2
                        valid = True

                        for i in range(left_count):
                            if count[sequence[i]] < 2:
                                valid = False
                                break

                        if valid:
                            max_length = max(max_length, length)

        return max_length

