    def maximumLength(self, nums: List[int]) -> int:
        from collections import Counter

        count = Counter(nums)
        max_length = 0

        # Handle x = 1 case specially
        if 1 in count:
            # For 1s: [1,1,1] pattern - maximum length is odd count
            max_length = count[1] if count[1] % 2 == 1 else count[1] - 1

